package br.com.estudiobdd.service;

import br.com.estudiobdd.dto.Requests.*;
import br.com.estudiobdd.dto.Responses.*;
import br.com.estudiobdd.model.*;
import br.com.estudiobdd.repository.*;
import jakarta.persistence.EntityNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import java.util.stream.Collectors;

@Service
@Transactional
public class EstudioService {
 private final UsuarioRepository usuarios; private final ProjetoRepository projetos; private final HistoriaUsuarioRepository historias; private final CenarioRepository cenarios; private final PassoRepository passos; private final SugestaoRepository sugestoes;
 public EstudioService(UsuarioRepository u,ProjetoRepository p,HistoriaUsuarioRepository h,CenarioRepository c,PassoRepository pa,SugestaoRepository s){usuarios=u;projetos=p;historias=h;cenarios=c;passos=pa;sugestoes=s;}
 private <T> T exigir(Optional<T> v,String msg){return v.orElseThrow(()->new EntityNotFoundException(msg));}
 public UsuarioRes criarUsuario(UsuarioReq r){Usuario u=usuarios.save(new Usuario(r.nome(),r.email()));return usuario(u);}
 public List<UsuarioRes> listarUsuarios(){return usuarios.findAll().stream().map(this::usuario).toList();}
 private UsuarioRes usuario(Usuario u){return new UsuarioRes(u.getId(),u.getNome(),u.getEmail());}
 public ProjetoRes criarProjeto(ProjetoReq r){return projeto(projetos.save(new Projeto(r.nome(),r.descricao(),r.contextoDominio())));}
 public List<ProjetoRes> listarProjetos(){return projetos.findAll().stream().map(this::projeto).toList();}
 public ProjetoRes atualizarProjeto(Long id,ProjetoReq r){Projeto p=exigir(projetos.findById(id),"Projeto não encontrado");p.setNome(r.nome());p.setDescricao(r.descricao());p.setContextoDominio(r.contextoDominio());return projeto(p);}
 public void excluirProjeto(Long id){projetos.delete(exigir(projetos.findById(id),"Projeto não encontrado"));}
 private ProjetoRes projeto(Projeto p){return new ProjetoRes(p.getId(),p.getNome(),p.getDescricao(),p.getContextoDominio(),p.getDataCriacao(),p.getHistorias().size());}
 public HistoriaRes criarHistoria(HistoriaReq r){Projeto p=exigir(projetos.findById(r.projetoId()),"Projeto não encontrado");Usuario a=exigir(usuarios.findById(r.autorId()),"Autor não encontrado");HistoriaUsuario h=new HistoriaUsuario(r.titulo(),r.papel(),r.objetivo(),r.beneficio(),r.prioridade(),p,a);return historia(historias.save(h));}
 public List<HistoriaRes> listarHistorias(Long projetoId,Prioridade prioridade){List<HistoriaUsuario> lista=prioridade==null?(projetoId==null?historias.findAll():historias.findByProjetoId(projetoId)):(projetoId==null?historias.findByPrioridade(prioridade):historias.findByProjetoIdAndPrioridade(projetoId,prioridade));return lista.stream().map(this::historia).toList();}
 public HistoriaRes obterHistoria(Long id){return historia(exigir(historias.findById(id),"História não encontrada"));}
 public HistoriaRes atualizarHistoria(Long id,HistoriaReq r,Long usuarioAtual){HistoriaUsuario h=exigir(historias.findById(id),"História não encontrada");if(!h.getAutor().getId().equals(usuarioAtual))throw new IllegalArgumentException("Somente o autor pode editar a história.");h.setTitulo(r.titulo());h.setPapel(r.papel());h.setObjetivo(r.objetivo());h.setBeneficio(r.beneficio());h.setPrioridade(r.prioridade());return historia(h);}
 public void excluirHistoria(Long id,Long usuarioAtual){HistoriaUsuario h=exigir(historias.findById(id),"História não encontrada");if(!h.getAutor().getId().equals(usuarioAtual))throw new IllegalArgumentException("Somente o autor pode excluir a história.");historias.delete(h);}
 public CenarioRes criarCenario(Long historiaId,CenarioReq r,Long usuarioAtual){HistoriaUsuario h=exigir(historias.findById(historiaId),"História não encontrada");if(!h.getAutor().getId().equals(usuarioAtual))throw new IllegalArgumentException("Somente o autor pode editar cenários.");int pos=r.posicao()==null?h.getCenarios().size()+1:r.posicao();Cenario c=new Cenario(r.titulo(),pos,r.origem());h.adicionarCenario(c);int indice=1;for(PassoReq pr:r.passos()){int ordem=pr.posicao()==null?indice:pr.posicao();c.adicionarPasso(new Passo(pr.tipo(),pr.texto(),ordem));indice++;}validarPassos(c.getPassos());cenarios.save(c);return cenario(c);}
 public PassoRes criarPasso(Long cenarioId,PassoReq r,Long usuarioAtual){Cenario c=exigir(cenarios.findById(cenarioId),"Cenário não encontrado");if(!c.getHistoria().getAutor().getId().equals(usuarioAtual))throw new IllegalArgumentException("Somente o autor pode editar cenários.");int pos=r.posicao()==null?c.getPassos().size()+1:r.posicao();Passo p=new Passo(r.tipo(),r.texto(),pos);c.adicionarPasso(p);validarPassos(c.getPassos());passos.save(p);return new PassoRes(p.getId(),p.getTipo(),p.getTexto(),p.getPosicao());}
 private void validarPassos(List<Passo> lista){List<Passo> ordenados=lista.stream().sorted(Comparator.comparing(Passo::getPosicao)).toList();if(ordenados.isEmpty())return;if(ordenados.get(0).getTipo()==TipoPasso.E||ordenados.get(0).getTipo()==TipoPasso.MAS)throw new IllegalArgumentException("E e MAS não podem iniciar um cenário.");boolean quando=false,entao=false;TipoPasso anterior=null;for(Passo p:ordenados){TipoPasso t=p.getTipo();if(t==TipoPasso.DADO&&quando)throw new IllegalArgumentException("DADO deve anteceder QUANDO.");if(t==TipoPasso.QUANDO)quando=true;if(t==TipoPasso.ENTAO){if(!quando)throw new IllegalArgumentException("ENTAO deve vir depois de QUANDO.");entao=true;}if((t==TipoPasso.E||t==TipoPasso.MAS)&&anterior==null)throw new IllegalArgumentException("E e MAS precisam continuar um tipo anterior.");anterior=t;}if(!quando)throw new IllegalArgumentException("O cenário precisa ter pelo menos um QUANDO.");if(!entao)throw new IllegalArgumentException("O cenário precisa ter pelo menos um ENTAO.");}

 public CenarioRes obterCenario(Long id){return cenario(exigir(cenarios.findById(id),"Cenário não encontrado"));}
 public CenarioRes atualizarCenario(Long id,String titulo,Long usuarioAtual){Cenario c=exigir(cenarios.findById(id),"Cenário não encontrado");if(!c.getHistoria().getAutor().getId().equals(usuarioAtual))throw new IllegalArgumentException("Somente o autor pode editar cenários.");c.setTitulo(titulo);return cenario(c);}
 public void excluirCenario(Long id,Long usuarioAtual){Cenario c=exigir(cenarios.findById(id),"Cenário não encontrado");if(!c.getHistoria().getAutor().getId().equals(usuarioAtual))throw new IllegalArgumentException("Somente o autor pode excluir cenários.");c.getHistoria().getCenarios().remove(c);cenarios.delete(c);}
 public PassoRes atualizarPasso(Long id,PassoReq r,Long usuarioAtual){Passo p=exigir(passos.findById(id),"Passo não encontrado");if(!p.getCenario().getHistoria().getAutor().getId().equals(usuarioAtual))throw new IllegalArgumentException("Somente o autor pode editar passos.");p.setTipo(r.tipo());p.setTexto(r.texto());p.setPosicao(r.posicao());validarPassos(p.getCenario().getPassos());return new PassoRes(p.getId(),p.getTipo(),p.getTexto(),p.getPosicao());}
 public void excluirPasso(Long id,Long usuarioAtual){Passo p=exigir(passos.findById(id),"Passo não encontrado");Cenario c=p.getCenario();if(!c.getHistoria().getAutor().getId().equals(usuarioAtual))throw new IllegalArgumentException("Somente o autor pode excluir passos.");c.getPassos().remove(p);passos.delete(p);validarPassos(c.getPassos());}
 public SugestaoRes criarSugestao(Long historiaId,SugestaoReq r){HistoriaUsuario h=exigir(historias.findById(historiaId),"História não encontrada");Usuario u=exigir(usuarios.findById(r.usuarioId()),"Usuário não encontrado");Sugestao s=new Sugestao(r.ferramenta(),r.promptUtilizado(),r.conteudo(),h,u);h.adicionarSugestao(s);return sugestao(sugestoes.save(s));}
 public SugestaoRes decidirSugestao(Long id,DecisaoReq r){Sugestao s=exigir(sugestoes.findById(id),"Sugestão não encontrada");if(s.getDecisao()!=DecisaoSugestao.PENDENTE)throw new IllegalArgumentException("Esta sugestão já foi decidida.");if(r.decisao()==DecisaoSugestao.PENDENTE)throw new IllegalArgumentException("Escolha ACEITA ou REJEITADA.");if(r.decisao()==DecisaoSugestao.REJEITADA&&r.motivoRejeicao()==null)throw new IllegalArgumentException("A rejeição exige um motivo.");Usuario u=exigir(usuarios.findById(r.usuarioId()),"Usuário não encontrado");s.decidir(r.decisao(),r.motivoRejeicao(),r.justificativa(),u);return sugestao(s);}
 public String exportarFeature(Long id){HistoriaUsuario h=exigir(historias.findById(id),"História não encontrada");if(h.getCenarios().isEmpty())throw new IllegalArgumentException("A história precisa ter ao menos um cenário para exportar.");if(h.getSugestoes().stream().anyMatch(s->s.getDecisao()==DecisaoSugestao.PENDENTE))throw new IllegalArgumentException("Resolva as sugestões pendentes antes de exportar.");StringBuilder b=new StringBuilder("# language: pt\n\nFuncionalidade: ").append(h.getTitulo()).append("\n  Como ").append(h.getPapel()).append("\n  Quero ").append(h.getObjetivo()).append("\n  Para ").append(h.getBeneficio()).append("\n\n");for(Cenario c:h.getCenarios()){validarPassos(c.getPassos());b.append("  Cenário: ").append(c.getTitulo()).append("\n");for(Passo p:c.getPassos().stream().sorted(Comparator.comparing(Passo::getPosicao)).toList())b.append("    ").append(palavraGherkin(p.getTipo())).append(" ").append(p.getTexto()).append("\n");b.append("\n");}return b.toString();}
 public Map<String,Object> resumo(Long projetoId){List<HistoriaUsuario> hs=projetoId==null?historias.findAll():historias.findByProjetoId(projetoId);Map<String,Object> m=new LinkedHashMap<>();m.put("totalHistorias",hs.size());m.put("totalCenarios",hs.stream().mapToInt(h->h.getCenarios().size()).sum());m.put("cenariosPorOrigem",hs.stream().flatMap(h->h.getCenarios().stream()).collect(Collectors.groupingBy(c->c.getOrigem().name(),Collectors.counting())));List<Sugestao> ss=hs.stream().flatMap(h->h.getSugestoes().stream()).toList();m.put("sugestoesPorDecisao",ss.stream().collect(Collectors.groupingBy(s->s.getDecisao().name(),Collectors.counting())));m.put("motivosRejeicao",ss.stream().filter(s->s.getMotivoRejeicao()!=null).collect(Collectors.groupingBy(s->s.getMotivoRejeicao().name(),Collectors.counting())));return m;}
 private String palavraGherkin(TipoPasso tipo){return switch(tipo){case DADO -> "Dado";case QUANDO -> "Quando";case ENTAO -> "Então";case E -> "E";case MAS -> "Mas";};}
 private HistoriaRes historia(HistoriaUsuario h){return new HistoriaRes(h.getId(),h.getTitulo(),h.getPapel(),h.getObjetivo(),h.getBeneficio(),h.getPrioridade(),h.getDataCriacao(),h.getDataAtualizacao(),h.getProjeto().getId(),h.getProjeto().getNome(),h.getAutor().getId(),h.getAutor().getNome(),h.getCenarios().stream().map(this::cenario).toList(),h.getSugestoes().stream().map(this::sugestao).toList());}
 private CenarioRes cenario(Cenario c){return new CenarioRes(c.getId(),c.getTitulo(),c.getPosicao(),c.getOrigem(),c.getPassos().stream().map(x->new PassoRes(x.getId(),x.getTipo(),x.getTexto(),x.getPosicao())).toList());}
 private SugestaoRes sugestao(Sugestao s){return new SugestaoRes(s.getId(),s.getFerramenta(),s.getPromptUtilizado(),s.getConteudo(),s.getDecisao(),s.getMotivoRejeicao(),s.getJustificativa(),s.getDataRegistro(),s.getDataDecisao(),s.getRegistradaPor().getId(),s.getDecididaPor()==null?null:s.getDecididaPor().getId());}
}
